# Identity, Wrapped pointers
struct MemoryHolder(ImplicitlyCopyable):
 var p: UnsafePointer[Int, MutExternalOrigin]

 def __init__(out self):
 self.p = alloc[Int](1)

 def __is__(self, other: MemoryHolder) -> Bool:
 return self.p == other.p

 def __isnot__(self, other: MemoryHolder) -> Bool:
 return not self.__is__(other)

 def __del__(deinit self):
 self.p.destroy_pointee()
 self.p.free()

...

var p1 = MemoryHolder(); var p2 = MemoryHolder()
print(p1 is p2) # False, two pointer allocations
print(p1 is not p2) # True, two pointer allocations
print(p1 is p1) # True, same pointer allocation

As an example, consider implementing support for all of the `+` operator dunder
methods for a custom `MyInt` struct. This shows supporting adding two `MyInt`
instances as well as adding a `MyInt` and an `Int`. We can support the case of
having the `Int` as the right-hand side argument by overloaded the definition of
`__add__()`. But to support the case of having the `Int` as the left-hand side
argument, we need to implement an `__radd__()` method, because the built-in
`Int` type doesn't have an `__add__()` method that supports our custom `MyInt`
type.

```mojo
@fieldwise_init
struct MyInt:
 var value: Int

 def __add__(self, rhs: MyInt) raises -> Self:
 return MyInt(self.value + rhs.value)

 def __add__(self, rhs: Int) raises -> Self:
 return MyInt(self.value + rhs)

def __add__(self, rhs: Int) raises -> Self:
 return MyInt(self.value + rhs)

 def __radd__(self, lhs: Int) raises -> Self:
 return MyInt(self.value + lhs)

 def __iadd__(mut self, rhs: MyInt) raises -> None:
 self.value += rhs.value

 def __iadd__(mut self, rhs: Int) raises -> None:
 self.value += rhs

```mojo
@fieldwise_init
struct MyInt(Comparable):
 var value: Int

 def __eq__(self, rhs: MyInt) -> Bool:
 return self.value == rhs.value

 def __lt__(self, rhs: MyInt) -> Bool:
 return self.value < rhs.value

 # `__ne__`, `__le__`, `__gt__`, and `__ge__` have default implementations.

### Implement basic indexing

Indexing usually is supported only by collection types. But as an example, let's
implement support for accessing the real component as index 0 and the imaginary
component as index 1. We'll not implement slicing or variadic assignment for
this example.

```mojo
 # ...
 def __getitem__(self, idx: Int) raises -> Float64:
 if idx == 0:
 return self.re
 elif idx == 1:
 return self.im
 else:
 raise "index out of bounds"

 def __setitem__(mut self, idx: Int, value: Float64) raises -> None:
 if idx == 0:
 self.re = value
 elif idx == 1:
 self.im = value
 else:
 raise "index out of bounds"

# ...

 def __add__(self, rhs: Self) raises -> Self:
 return Self(self.re + rhs.re, self.im + rhs.im)

 def __sub__(self, rhs: Self) raises -> Self:
 return Self(self.re - rhs.re, self.im - rhs.im)

 def __mul__(self, rhs: Self) raises -> Self:
 return Self(
 self.re * rhs.re - self.im * rhs.im,
 self.re * rhs.im + self.im * rhs.re
 )

 def __truediv__(self, rhs: Self) raises -> Self:
 denom = rhs.squared_norm()
 return Self(
 (self.re * rhs.re + self.im * rhs.im) / denom,
 (self.im * rhs.re - self.re * rhs.im) / denom
 )

def squared_norm(self) raises -> Float64:
 return self.re * self.re + self.im * self.im

 def norm(self) raises -> Float64:
 return sqrt(self.squared_norm())

So we can support arithmetic operations on `Complex` and `Float64` values by
implementing the following eight methods.

```mojo
 # ...
 def __add__(self, rhs: Float64) raises -> Self:
 return Self(self.re + rhs, self.im)

 def __radd__(self, lhs: Float64) raises -> Self:
 return Self(self.re + lhs, self.im)

 def __sub__(self, rhs: Float64) raises -> Self:
 return Self(self.re - rhs, self.im)

 def __rsub__(self, lhs: Float64) raises -> Self:
 return Self(lhs - self.re, -self.im)

 def __mul__(self, rhs: Float64) raises -> Self:
 return Self(self.re * rhs, self.im * rhs)

def __mul__(self, rhs: Float64) raises -> Self:
 return Self(self.re * rhs, self.im * rhs)

 def __rmul__(self, lhs: Float64) raises -> Self:
 return Self(lhs * self.re, lhs * self.im)

 def __truediv__(self, rhs: Float64) raises -> Self:
 return Self(self.re / rhs, self.im / rhs)

 def __rtruediv__(self, lhs: Float64) raises -> Self:
 denom = self.squared_norm()
 return Self(
 (lhs * self.re) / denom,
 (-lhs * self.im) / denom
 )

def __isub__(mut self, rhs: Self) raises -> None:
 self.re -= rhs.re
 self.im -= rhs.im

 def __isub__(mut self, rhs: Float64) raises -> None:
 self.re -= rhs

 def __imul__(mut self, rhs: Self) raises -> None:
 new_re = self.re * rhs.re - self.im * rhs.im
 new_im = self.re * rhs.im + self.im * rhs.re
 self.re = new_re
 self.im = new_im

 def __imul__(mut self, rhs: Float64) raises -> None:
 self.re *= rhs
 self.im *= rhs
